    # ── COMPARATIVE LAW — CIVIL VS CRIMINAL APPROACHES ────────────────────────
    {
        "type": "law",
        "jurisdiction": "US",
        "title": "Fair Labor Standards Act — Application to Diplomatic Domestic Workers",
        "summary": "The Fair Labor Standards Act (FLSA) sets federal minimum wage and overtime requirements. Courts have held that FLSA applies to domestic workers employed in the US regardless of the employer's nationality. The question of diplomatic immunity's interaction with FLSA civil claims has been litigated in multiple A-3/G-5 cases. Courts have generally found that FLSA claims are subject to the same immunity analysis as TVPA claims: if the commercial activity exception applies, both FLSA and TVPA claims can proceed. DOL Wage and Hour Division has issued guidance that it will refer FLSA complaints involving diplomatic employers to the State Department.",
        "source": "29 USC §201 / DOL WHD Guidance 2016 / FLSA Litigation History",
    },
    {
        "type": "law",
        "jurisdiction": "EU",
        "title": "EU Posted Workers Directive — Non-Application to Diplomatic Domestic Workers",
        "summary": "The EU's Posted Workers Directive (96/71/EC and 2018 revision) guarantees minimum wage and working conditions of the host member state to workers posted from other EU states. However, it does not apply to diplomatic domestic workers because the employer is not a commercial entity posting the worker in the course of transnational service provision. This regulatory gap means a domestic worker brought by a diplomat from one EU state to another cannot use the Posted Workers Directive as a basis for a wage claim. EU legal scholars have proposed a diplomatic domestic worker supplement to the Directive.",
        "source": "EU Posted Workers Directive / European Commission DG EMPL",
    },
