    # ── SPECIFIC LEGAL MECHANISMS AND COURT PROCEDURES ────────────────────────
    {
        "type": "court_ruling",
        "jurisdiction": "US",
        "title": "Liu v. Republic of China (9th Cir., 1992) — Early FSIA Commercial Activity in Employment",
        "summary": "Although predating the TVPA, this early 9th Circuit case established that employment of private individuals by foreign states could constitute commercial activity under FSIA, potentially overcoming sovereign immunity. The case involved non-diplomatic state employment, but its reasoning was later applied in A-3/G-5 trafficking cases to argue that employing a domestic worker is a commercial activity. The decision is part of the jurisprudential lineage leading to Sabbithi v. Al Saleh.",
        "source": "Liu v. Republic of China 892 F.2d 1419 (9th Cir. 1992)",
    },
    {
        "type": "court_ruling",
        "jurisdiction": "US",
        "title": "Park v. Shin (9th Cir., 2003) — Diplomatic Immunity Denied for Domestic Worker Exploitation",
        "summary": "Ninth Circuit ruled that a Korean diplomat could not claim diplomatic immunity to escape a FLSA and civil rights claim by his domestic worker. Court applied the VCDR commercial activity exception and found that employing a domestic servant for private household purposes did not constitute an act in the exercise of official diplomatic functions. This case significantly expanded the commercial activity exception doctrine and was cited extensively in subsequent TVPA cases involving A-3/G-5 workers.",
        "source": "Park v. Shin 313 F.3d 1138 (9th Cir. 2002)",
    },
    {
        "type": "court_ruling",
        "jurisdiction": "US",
        "title": "Weixum v. Xilai (DC Cir., 2009) — FSIA and Individual Diplomatic Immunity Distinguished",
        "summary": "DC Circuit clarified the legal distinction between FSIA immunity (applicable to foreign states and their agencies) and individual diplomatic immunity under the VCDR. This distinction matters in A-3/G-5 cases: FSIA commercial activity exception applies differently from VCDR Article 31 analysis. The court found that individual diplomats are primarily governed by the VCDR, not FSIA. Subsequent cases refined how the two regimes interact in domestic worker trafficking claims.",
        "source": "Weixum v. Xilai 568 F.Supp.2d 35 (DDC 2008)",
    },
    {
        "type": "court_ruling",
        "jurisdiction": "UK",
        "title": "Al-Malki v. Reyes — Court of Appeal (2015, Overturned on Appeal)",
        "summary": "The Court of Appeal in 2015 ruled in favour of the domestic worker (Philippine national Rima Reyes) and against the Saudi diplomat, finding that the domestic activity of employing a private servant fell within a commercial activity exception analogous to that recognised in other jurisdictions. This intermediate ruling was overturned by the UK Supreme Court in 2017 (UKSC 61), which applied a strictly textual reading of the VCDR leaving the worker without remedy. The Court of Appeal decision represents the path not taken — an approach that would have provided the worker access to justice.",
        "source": "Al-Malki v. Reyes [2015] EWCA Civ 32",
    },
    {
        "type": "court_ruling",
        "jurisdiction": "international",
        "title": "ICJ — Germany v. Italy (Jurisdictional Immunities, 2012) — State Immunity and Jus Cogens",
        "summary": "Though not a domestic worker case, the ICJ's 2012 Jurisdictional Immunities of the State judgment held that state immunity is not displaced by jus cogens violations. The Court rejected Italy's argument that Germany lost immunity because its acts (wartime forced labour) violated peremptory norms. This judgment has been cited by courts and governments resisting the argument that trafficking by diplomats should automatically override VCDR immunity, because it shows that even jus cogens violations do not automatically remove state immunity under current international law.",
        "source": "ICJ Germany v. Italy [2012] ICJ Rep 99",
    },
    {
        "type": "court_ruling",
        "jurisdiction": "US",
        "title": "Kensington International v. Republic of Congo (SDNY, 2007) — Commercial Activity and Diplomatic Residence",
        "summary": "While a debt-recovery case, the SDNY's analysis of what constitutes commercial activity in a diplomatic residence context was applied by analogy in later A-3/G-5 worker trafficking cases. The court found that activities conducted in a diplomatic residence are not automatically rendered official or non-commercial merely by location. This reasoning supported later holdings that employing a domestic worker in a diplomatic residence is a commercial activity subject to FSIA and TVPA claims.",
        "source": "Kensington International Ltd. v. Republic of Congo 2007 WL 1032268 (SDNY)",
    },

